/**
 * Poll until OpenRouter exists on the canonical provider &lt;select&gt; (preset lane + CI hydration lag).
 * Harness-only; bounded by caller (no global timeout inflation).
 */
async function waitForOpenRouterOptionAfterPreset(page, budgetMs) {
    const deadline = Date.now() + Math.max(0, budgetMs);
    let last = { ok: false, reason: 'not-started', n: 0 };
    while (Date.now() < deadline) {
        last = await page
            .evaluate(() => {
                const box = document.querySelector('[data-testid="settings-connection-controls"]');
                const el = box && box.querySelector('[data-testid="settings-provider-select"]');
                if (!(el instanceof HTMLSelectElement)) {
                    return { ok: false, reason: 'not-select', n: 0 };
                }
                const opts = [...el.options].map((o) => String(o.value || ''));
                const has = opts.some((v) => v === 'openrouter');
                const r = el.getBoundingClientRect();
                return {
                    ok: has,
                    reason: has ? 'ok' : 'missing-option',
                    n: opts.length,
                    head: opts.slice(0, 8),
                    h: r && r.height > 0.5,
                };
            })
            .catch((e) => ({ ok: false, reason: 'evaluate-error', n: 0, err: e?.message || String(e) }));
        if (last.ok) return last;
        await page.waitForTimeout(220);
    }
    return last;
}

