    await expect(openDrawerLocator).toHaveCount(0, { timeout: 8000 });
};

/**
 * Re-resolve the open drawer close target, click, and tolerate the race where the drawer
 * dismisses during Playwright's internal click action (timeout) while the final DOM is already closed.
 */
const runCloseClickAttempt = async (timeoutMs, phaseTag) => {
    logSettingsCloseHarness('phase', String(phaseTag || '').slice(0, 96));

    const drawerCtBefore = await pg.locator('[data-testid="settings-drawer"]').count().catch(() => -1);
    let openCtBefore = await openDrawerLocator.count().catch(() => -1);
    logSettingsCloseHarness('open-drawer-count-before-click', openCtBefore);
    logSettingsCloseHarness('drawer-count-before-click', drawerCtBefore);

    if (openCtBefore === 0) {
        logSettingsCloseHarness('already-closed-before-click', true);
        return true;
    }

    drawer = await getActiveSettingsDrawer();
    closeBtn = drawer.getByTestId('settings-close-btn');
    await assertCloseButtonReady();

    const btnAttached = await closeBtn.count().catch(() => 0);
    const btnVisible = await drawer
        .getByTestId('settings-close-btn')
        .filter({ visible: true })
        .count()
        .catch(() => 0);
    const disabled = await closeBtn.first().isDisabled().catch(() => true);
    const ariaDis = await closeBtn.first().getAttribute('aria-disabled').catch(() => null);
    const effectivelyEnabled = !disabled && ariaDis !== 'true';

    logSettingsCloseHarness('button-attached-count', btnAttached);
    logSettingsCloseHarness('button-visible-count', btnVisible);
    logSettingsCloseHarness('button-enabled', effectivelyEnabled);

    const closeTarget = closeBtn.first();
    await closeTarget.scrollIntoViewIfNeeded().catch(() => {});

    logSettingsCloseHarness('click-attempted', true);

    try {
        await closeTarget.click({ timeout: timeoutMs, noWaitAfter: true });
    } catch (err) {
        const openAfterAttempt = await openDrawerLocator.count().catch(() => -1);
        const drawerCtAfter = await pg.locator('[data-testid="settings-drawer"]').count().catch(() => -1);
        logSettingsCloseHarness('open-drawer-count-after-click-attempt', openAfterAttempt);
        logSettingsCloseHarness('drawer-count-after-click-attempt', drawerCtAfter);
        const d = await snap();
        const domLine = JSON.stringify({
            openAfterAttempt,
            drawerCtAfter,
            drawerCount: d && d.drawerCount,
            openDrawerCount: d && d.openDrawerCount,
            evaluateError: d && d.evaluateError,
        }).slice(0, 480);
        logSettingsCloseHarness('click-timeout-dom-state', domLine);
        if (openAfterAttempt === 0) {
            logSettingsCloseHarness('closed-during-click-timeout', true);
            await confirmDrawerClosed();
            return true;
        }
        throw err;
    }

    const openAfterAttempt = await openDrawerLocator.count().catch(() => -1);
    const drawerCtAfter = await pg.locator('[data-testid="settings-drawer"]').count().catch(() => -1);
    logSettingsCloseHarness('open-drawer-count-after-click-attempt', openAfterAttempt);
    logSettingsCloseHarness('drawer-count-after-click-attempt', drawerCtAfter);

    try {
        await confirmDrawerClosed();
        return true;
    } catch {
        return false;
    }
};

const preOpen = await openDrawerLocator.count().catch(() => 0);
if (preOpen === 0) {
    logSettingsCloseHarness('phase', 'pre-first-click-skip');
    logSettingsCloseHarness('already-closed-before-click', true);
    await attachJsonSnapshot(`${base}-after.json`, {
        classification: 'settings-close-ok',
        reasonLabel: label,
        elapsedMs: Date.now() - started,
        skipReason: 'already-closed-before-first-attempt',
        ...(await snap()),
    });
    return;
}

let clickOk = false;
try {
    clickOk = await runCloseClickAttempt(8000, 'first-click');
} catch (err) {
    await writeFailed(classifyClickErr(err), err, { phase: 'first-click' });
    throw err;
}

if (!clickOk) {
    await dismissBlockingOverlaysNoBackdrop({ budgetMs: 12000 });
    try {
        drawer = await getActiveSettingsDrawer();
        closeBtn = drawer.getByTestId('settings-close-btn');
    } catch (err) {
        await writeFailed('settings-close-click-not-committed', err, { phase: 'after-first-click-reacquire' });
        throw err;
    }
    try {
        clickOk = await runCloseClickAttempt(6000, 'second-click-after-overlay-dismiss');
    } catch (err) {
        await writeFailed(classifyClickErr(err), err, { phase: 'second-click-after-overlay-dismiss' });
        throw err;
    }
}

